#include <sys/types.h>

#include <fcntl.h>
#include <string.h>
#include <unistd.h>

#include "tmux.h"

#ifdef GRID_VMF_HISTORY
#include <vmf.h>

/*
 * Window history kept in a paging file through vmf(3), the 2.11BSD library
 * its own cpp and ld use for tables that do not fit a 64K data space.
 *
 * One anonymous file serves the whole server. A grid with history owns a
 * slot of GRID_HISTORY_SEGMENTS consecutive 1024-byte segments and uses it
 * as a ring of fixed-size records, GRID_HISTORY_PERSEG to a segment so that
 * no record crosses a segment boundary:
 *
 *	byte 0		line flags (GRID_LINE_WRAPPED)
 *	byte 1		number of characters, at most GRID_HISTORY_COLUMNS
 *	bytes 2..81	characters
 *
 * vmf keeps GRID_HISTORY_BUFFERS segments in memory, about 1K each, however
 * many windows there are and however long their history; that is the whole
 * cost to the data space. Rows are appended and read one at a time, so
 * nothing here holds a segment pointer across a second vmf call.
 *
 * vmf ends the process if it cannot write a segment out. A full /tmp must
 * not take every session with it, so a segment's blocks are written here,
 * where failure can be handled, before vmf is first asked for the segment.
 * If that write fails the ring simply stops growing.
 */

/*
 * The geometry in tmux.h must fit vmf's: GRID_HISTORY_PERSEG records in
 * BYTESPERSEG bytes and every slot below MAXSEGNO. tests/vmf-history.c
 * checks it; the native preprocessor is not asked to do the arithmetic.
 */

static struct vspace	 grid_history_space;
static int		 grid_history_state;	/* 0 unopened, 1 usable, -1 not */
static u_int		 grid_history_used;	/* bit per slot in use */

/* Segments of each slot whose file blocks have been written. */
static u_char		 grid_history_ready[GRID_HISTORY_SLOTS];

/* The row most recently fetched, and a scratch record. */
static struct grid	*grid_history_cached;
static u_int		 grid_history_cached_py;
static u_char		 grid_history_record[GRID_HISTORY_RECORD];

static int
grid_history_start(void)
{
	if (grid_history_state != 0)
		return (grid_history_state > 0);
	grid_history_state = -1;

	if (vminit(GRID_HISTORY_BUFFERS) != 0)
		return (0);
	if (vmopen(&grid_history_space, (char *)NULL) < 0)
		return (0);
	/* Shells started in windows must not inherit the paging file. */
	(void)fcntl(grid_history_space.v_fd, F_SETFD, 1);

	grid_history_state = 1;
	return (1);
}

/* Write the blocks of segment si of a slot. */
static int
grid_history_allocate(u_int slot, u_int si)
{
	off_t	where;
	u_int	left, n;

	where = (off_t)(slot * GRID_HISTORY_SEGMENTS + si) * BYTESPERSEG +
	    grid_history_space.v_foffset;
	if (lseek(grid_history_space.v_fd, where, 0) == (off_t)-1)
		return (-1);

	grid_history_cached = NULL;
	memset(grid_history_record, 0, sizeof grid_history_record);
	for (left = BYTESPERSEG; left > 0; left -= n) {
		n = left;
		if (n > sizeof grid_history_record)
			n = sizeof grid_history_record;
		if (write(grid_history_space.v_fd,
		    grid_history_record, n) != (int)n)
			return (-1);
	}
	grid_history_ready[slot] = si + 1;
	return (0);
}

/* Give a new grid a slot. Without one it has no history. */
void
grid_history_open(struct grid *gd)
{
	u_int	slot;

	gd->hslot = 0;
	gd->hhead = 0;
	if (gd->hlimit == 0)
		return;

	if (grid_history_start()) {
		for (slot = 0; slot < GRID_HISTORY_SLOTS; slot++) {
			if (!(grid_history_used & (1U << slot)))
				break;
		}
		if (slot < GRID_HISTORY_SLOTS) {
			grid_history_used |= 1U << slot;
			gd->hslot = slot + 1;
			if (gd->hlimit > GRID_HISTORY_ROWS)
				gd->hlimit = GRID_HISTORY_ROWS;
			return;
		}
	}
	gd->hlimit = 0;
	gd->flags &= ~GRID_HISTORY;
}

/* Release the slot of a grid being destroyed. Its rows are not erased. */
void
grid_history_close(struct grid *gd)
{
	if (gd->hslot == 0)
		return;
	grid_history_used &= ~(1U << (gd->hslot - 1));
	gd->hslot = 0;
	if (grid_history_cached == gd)
		grid_history_cached = NULL;
}

/* Forget every history row. */
void
grid_history_clear(struct grid *gd)
{
	gd->hsize = 0;
	gd->hhead = 0;
	if (grid_history_cached == gd)
		grid_history_cached = NULL;
}

/* Stop keeping history for a grid whose first segment cannot be written. */
static void
grid_history_abandon(struct grid *gd)
{
	grid_history_clear(gd);
	grid_history_close(gd);
	gd->hlimit = 0;
	gd->flags &= ~GRID_HISTORY;
}

/*
 * Store a row as the newest history row. When the ring is full the oldest
 * row is overwritten, so hsize stays at hlimit.
 */
void
grid_history_push(struct grid *gd, const struct grid_line *gl)
{
	struct vseg	*seg;
	u_char		*rp;
	const u_char	*sp;
	u_int		 slot, pos, si, n, xx;

	if (gd->hslot == 0 || gd->hlimit == 0)
		return;
	slot = gd->hslot - 1;

	if (gd->hsize < gd->hlimit) {
		/*
		 * Still growing, so hhead is 0 and this is the first use of
		 * position hsize.
		 */
		pos = gd->hsize;
		si = pos / GRID_HISTORY_PERSEG;
		if (si >= grid_history_ready[slot] &&
		    grid_history_allocate(slot, si) != 0) {
			if (si == 0) {
				grid_history_abandon(gd);
				return;
			}
			/* The ring is as large as it can get. */
			gd->hlimit = pos;
		}
	}
	if (gd->hsize < gd->hlimit)
		gd->hsize++;
	else {
		pos = gd->hhead;
		gd->hhead = (gd->hhead + 1) % gd->hlimit;
	}
	si = pos / GRID_HISTORY_PERSEG;

	grid_history_cached = NULL;
	seg = vmmapseg(&grid_history_space, slot * GRID_HISTORY_SEGMENTS + si);
	rp = (u_char *)seg->s_cinfo +
	    (pos % GRID_HISTORY_PERSEG) * GRID_HISTORY_RECORD;

	n = gl->cellsize;
	if (n > GRID_HISTORY_COLUMNS)
		n = GRID_HISTORY_COLUMNS;
	rp[0] = gl->flags & GRID_LINE_WRAPPED;
	rp[1] = n;
	if (n != 0)
		memcpy(rp + 2, gl->chardata, n);
	if (gl->styledata != NULL) {
		/* Cells that are not one plain character in the row. */
		sp = gl->styledata + 1;
		for (xx = 0; xx < n; xx++) {
			if (*sp & GRID_FLAG_PADDING)
				rp[2 + xx] = ' ';
			else if (*sp & GRID_FLAG_UTF8)
				rp[2 + xx] = '_';
			sp += GRID_STYLE_BYTES;
		}
	}
	vmmodify(seg);
}

/*
 * The record of history row py, which must be below hsize. The result is
 * valid until the next call to any function in this file.
 */
const u_char *
grid_history_row(struct grid *gd, u_int py)
{
	struct vseg	*seg;
	u_int		 pos;

	if (grid_history_cached == gd && grid_history_cached_py == py)
		return (grid_history_record);

	if (gd->hslot == 0 || py >= gd->hsize) {
		grid_history_cached = NULL;
		memset(grid_history_record, 0, sizeof grid_history_record);
		return (grid_history_record);
	}

	pos = (gd->hhead + py) % gd->hlimit;
	seg = vmmapseg(&grid_history_space, (gd->hslot - 1) *
	    GRID_HISTORY_SEGMENTS + pos / GRID_HISTORY_PERSEG);
	memcpy(grid_history_record, (u_char *)seg->s_cinfo +
	    (pos % GRID_HISTORY_PERSEG) * GRID_HISTORY_RECORD,
	    sizeof grid_history_record);
	grid_history_cached = gd;
	grid_history_cached_py = py;
	return (grid_history_record);
}
#endif
